import React from 'react';
import ListDropDown from '../../Common/ListDropDown';
import CustomButton from '../../../../components/CustomButton';

// onSetup / onOpen are given only to the super admin: Set up opens the first-time setup of that school, Open makes it the school the
// whole app works in. isCurrent marks the school the app is working in now.
// A school cannot be deleted from here: the server only removes a school with nothing linked to it and otherwise answers with a
// misleading "No record found", and deleting a school would take all its data with it. So the menu only has Edit.
const SchoolList = ({ schoolItem, fetchSchool, onSetup, onOpen, isCurrent }) => {
  return (
    <tr>
      <td>{schoolItem.schoolCode}</td>
      <td>
        {schoolItem.schoolName}
        {isCurrent && (
          <span
            style={{
              marginLeft: 8,
              padding: '1px 8px',
              borderRadius: 999,
              fontSize: 11,
              fontWeight: 700,
              background: '#ede1f7',
              color: '#5b1584',
            }}>
            Current
          </span>
        )}
      </td>
      <td>{schoolItem.address}</td>
      <td>{schoolItem.phoneNumber}</td>
      <td>{schoolItem.country}</td>
      <td>{schoolItem.currencyType}</td>
      <td className="text-center">
        <div style={{ display: 'inline-flex', alignItems: 'center', gap: 10 }}>
          {onOpen && !isCurrent && (
            <CustomButton size="small" variant="outlined" name="Open" onClick={() => onOpen(schoolItem)} />
          )}
          {onSetup && <CustomButton size="small" variant="outlined" name="Setup" onClick={() => onSetup(schoolItem)} />}
          <ListDropDown actionList={['edit']} item={schoolItem} fetchItem={() => fetchSchool(schoolItem.schoolId)} />
        </div>
      </td>
    </tr>
  );
};

export default SchoolList;
