import { setGlobalSchoolUtils } from 'utils/commonFunc';

// Make another school the one the whole app works in (the super admin can work in every school). The saved batch belongs to the
// old school, so it is dropped; the top bar then saves the new school's running-year batch. A full load of the dashboard starts the
// app fresh on the new school, so nothing of the old school is left on any page.
export const switchSchool = school => {
  if (!school?.schoolId) return;
  setGlobalSchoolUtils({
    schoolId: school.schoolId,
    schoolCode: school.schoolCode,
    language: school.language,
    schoolName: school.schoolName,
  });
  try {
    window.localStorage.removeItem('currentBatch');
    window.localStorage.removeItem('actualCurrentBatch');
  } catch (e) {
    // no saved batch to drop
  }
  window.location.assign('/admin/dashboard');
};
